# ===================== INTEREST → COLLEGE CATEGORY MAPPING =====================
# Maps each "Pick Your Interests" option to one or more college DB categories

INTEREST_TO_CATEGORIES: dict = {
    "Coding / Tech":      ["engineering"],
    "Medicine / Health":  ["medical", "nursing", "pharmacy"],
    "Teaching":           ["teaching", "arts"],
    "Drawing / Art":      ["design", "arts"],
    "Business":           ["commerce", "management"],
    "Agriculture":        ["agriculture"],
    "Sports":             ["arts", "engineering"],   # physical education, sports science
    "Music":              ["arts", "design"],         # performing arts
    "Government Jobs":    ["engineering", "arts", "commerce", "law"],
    "Banking / Finance":  ["commerce", "management"],
    "Science Research":   ["engineering", "medical", "agriculture"],
    "Social Work":        ["arts", "teaching"],
    "Law / Legal":        ["law"],
    "Engineering":        ["engineering"],
    "Nursing / Care":     ["nursing", "medical"],
    "Fashion / Design":   ["design"],
    "Animation / Media":  ["design", "arts"],
    "Pharmacy":           ["pharmacy", "medical"],
    "Architecture":       ["engineering"],            # B.Arch in engg category
    "Defense / Army":     ["engineering", "arts"],    # NDA requires PCM/PCB
}


def get_colleges_for_category_raw(profile, category: str, count: int = 100) -> list:
    """Return colleges from a specific category, filtered by budget + location, with images."""
    all_colleges = MASSIVE_COLLEGE_DB.get(category, [])

    budget_max = _parse_budget(profile.budget_for_education)
    budget_filtered = [c for c in all_colleges
                       if _parse_fees(c.get("annual_fees", "0")) <= budget_max]
    # Progressively relax budget until we have enough colleges
    if len(budget_filtered) < count:
        budget_filtered = [c for c in all_colleges
                           if _parse_fees(c.get("annual_fees", "0")) <= budget_max * 1.5]
    if len(budget_filtered) < count:
        budget_filtered = list(all_colleges)

    state = profile.location.lower()
    nearby = [c for c in budget_filtered if _is_nearby_state(state, c.get("location", "").lower())]
    others = [c for c in budget_filtered if not _is_nearby_state(state, c.get("location", "").lower())]

    sorted_colleges = nearby + others
    return _assign_unique_images(sorted_colleges[:count], category)


def get_colleges_by_interest(interest: str, profile, count: int = 80) -> list:
    """
    Return up to `count` colleges relevant to a specific interest.
    Merges across mapped categories, deduplicates by name.
    """
    categories = INTEREST_TO_CATEGORIES.get(interest, ["engineering"])
    per_cat = max(count // len(categories) + 20, 50)

    seen_names: set = set()
    merged: list = []

    for cat in categories:
        for college in get_colleges_for_category_raw(profile, cat, count=per_cat):
            name = college.get("name", "")
            if name and name not in seen_names:
                seen_names.add(name)
                merged.append(college)

    return merged[:count]


def _assign_unique_images(colleges: list, category: str) -> list:
    """Assign a unique image URL to each college based on category pool + name hash.
    Uses MD5 hash of college name for consistent, non-sequential image selection,
    ensuring the same college always gets the same image and nearby colleges differ."""
    import hashlib
    pool = CATEGORY_IMAGE_POOLS.get(category, CATEGORY_IMAGE_POOLS["engineering"])
    result = []
    for college in colleges:
        c = dict(college)
        name_key = (c.get("name") or str(id(c))).strip().lower()
        idx = int(hashlib.md5(name_key.encode()).hexdigest(), 16) % len(pool)
        c["image_url"] = pool[idx]
        result.append(c)
    return result


import re


def _parse_fees(fees_str: str) -> int:
    """Extract numeric annual fees from string"""
    try:
        clean = fees_str.replace(",", "")
        numbers = re.findall(r"\d+", clean.split("/")[0])
        return int(numbers[0]) if numbers else 999999
    except:
        return 999999


def get_filtered_colleges(profile, career_category: str = "engineering", count: int = 12) -> list:
    """
    Smart college filtering based on student profile:
    - education_level -> right category (10th->ITI, 12th->UG, Grad->PG)
    - stream -> right category (Science->engg/medical, Commerce->commerce, Arts->arts/law)
    - budget -> annual fees filter
    - location -> state-proximity sorting
    """
    # Determine category from education + stream + career
    category = _determine_category(profile, career_category)
    all_colleges = MASSIVE_COLLEGE_DB.get(category, [])

    # Budget filter
    budget_max = _parse_budget(profile.budget_for_education)
    budget_filtered = []
    for c in all_colleges:
        fees = _parse_fees(c.get("annual_fees", "0"))
        if fees <= budget_max:
            budget_filtered.append(c)

    # If fewer than requested count after budget filter, progressively relax budget
    if len(budget_filtered) < count:
        # Try 1.5x budget
        budget_filtered_relaxed = []
        for c in all_colleges:
            fees = _parse_fees(c.get("annual_fees", "0"))
            if fees <= budget_max * 1.5:
                budget_filtered_relaxed.append(c)
        if len(budget_filtered_relaxed) >= len(budget_filtered):
            budget_filtered = budget_filtered_relaxed
    # Still not enough? Use all colleges
    if len(budget_filtered) < count:
        budget_filtered = all_colleges

    # Location sort: prioritize state-nearby colleges
    state = profile.location.lower()
    nearby = []
    others = []
    for c in budget_filtered:
        loc = c.get("location", "").lower()
        if _is_nearby_state(state, loc):
            nearby.append(c)
        else:
            others.append(c)

    sorted_colleges = nearby + others
    # Assign unique images from category pool before returning
    return _assign_unique_images(sorted_colleges[:count], category)


def _determine_category(profile, career_category: str) -> str:
    """Map education level + stream + career to college category"""
    edu = profile.education_level.lower()
    stream = (profile.stream or "").lower()
    career_lower = career_category.lower()

    # 10th pass -> ITI/Polytechnic
    if "10th" in edu or "class 10" in edu:
        return "iti_polytechnic"

    # Determine by career/stream
    if any(w in career_lower for w in ["engineer", "software", "developer", "computer", "it", "cse", "technical"]):
        return "engineering"
    if any(w in career_lower for w in ["doctor", "medical", "mbbs", "medicine", "physician"]):
        return "medical"
    if any(w in career_lower for w in ["nurse", "nursing", "bsc nursing"]):
        return "nursing"
    if any(w in career_lower for w in ["teacher", "teaching", "education", "professor", "b.ed", "bed"]):
        return "teaching"
    if any(w in career_lower for w in ["pharmacy", "pharmacist", "b.pharm", "bpharm"]):
        return "pharmacy"
    if any(w in career_lower for w in ["agriculture", "farming", "agri", "bsc agri", "horticulture"]):
        return "agriculture"
    if any(w in career_lower for w in ["commerce", "accountant", "ca", "finance", "business", "bcom", "mba", "banking"]):
        return "commerce"
    if any(w in career_lower for w in ["law", "lawyer", "legal", "llb", "clat"]):
        return "law"
    if any(w in career_lower for w in ["arts", "history", "political", "sociology", "psychology", "humanities"]):
        return "arts"
    if any(w in career_lower for w in ["mba", "management", "manager", "business administration", "pgdm", "iim"]):
        return "management"
    if any(w in career_lower for w in ["design", "fashion", "nift", "nid", "animation", "graphic", "ui/ux", "visual art", "interior design"]):
        return "design"

    # Fallback by stream
    if "science" in stream:
        return "engineering"
    if "commerce" in stream:
        return "commerce"
    if "arts" in stream:
        return "arts"

    return "engineering"


def _parse_budget(budget_str: str) -> int:
    """Parse budget string to max annual fees integer"""
    b = budget_str.lower()
    if "<50k" in b or "50k" in b:
        return 50000
    if "50k-1l" in b or "1l" in b:
        return 100000
    if "1-3l" in b or "1l-3l" in b:
        return 300000
    if "3l+" in b or "3l" in b:
        return 9999999
    return 300000  # default


def _is_nearby_state(student_state: str, college_location: str) -> bool:
    """Check if college is in or near the student's state"""
    nearby_map = {
        "bihar": ["patna", "bihar", "varanasi", "jharkhand", "bhu", "prayagraj"],
        "uttar pradesh": ["lucknow", "kanpur", "varanasi", "prayagraj", "noida", "delhi", "agra"],
        "maharashtra": ["mumbai", "pune", "nagpur", "maharashtra", "aurangabad"],
        "tamil nadu": ["chennai", "tamil", "madurai", "coimbatore", "vellore", "trichy"],
        "rajasthan": ["jaipur", "jodhpur", "rajasthan", "pilani", "bikaner", "udaipur"],
        "west bengal": ["kolkata", "bengal", "kharagpur", "howrah", "durgapur"],
        "gujarat": ["ahmedabad", "surat", "gujarat", "gandhinagar", "vadodara"],
        "karnataka": ["bangalore", "mysore", "karnataka", "mangalore", "hubli"],
        "telangana": ["hyderabad", "telangana", "warangal"],
        "andhra pradesh": ["vijayawada", "vizag", "andhra", "tirupati"],
        "madhya pradesh": ["bhopal", "indore", "madhya", "jabalpur"],
        "chhattisgarh": ["raipur", "chhattisgarh", "bilaspur"],
        "odisha": ["bhubaneswar", "rourkela", "odisha", "cuttack"],
        "jharkhand": ["ranchi", "jharkhand", "dhanbad"],
        "assam": ["guwahati", "assam", "silchar", "tezpur", "jorhat"],
        "punjab": ["ludhiana", "chandigarh", "punjab", "amritsar", "patiala"],
        "haryana": ["chandigarh", "gurgaon", "haryana", "rohtak", "kurukshetra"],
        "kerala": ["kozhikode", "kerala", "thiruvananthapuram", "ernakulam"],
        "delhi": ["new delhi", "delhi", "noida", "ncr"],
        "uttarakhand": ["rishikesh", "dehradun", "uttarakhand", "roorkee"],
    }
    for state_key, keywords in nearby_map.items():
        if state_key in student_state:
            return any(kw in college_location for kw in keywords)
    # fallback: check if any word from student state is in college location
    state_words = student_state.replace(",", " ").split()
    for w in state_words:
        if len(w) > 3 and w in college_location:
            return True
    return False
